import { RESOURCE_DEFS, RESOURCE_MERGE_RECIPES } from "../../game/config/resource-config.js";

const p = (text) => ({ type: "paragraph", text });
const tip = (title, text) => ({ type: "tip", title, text });
const steps = (title, items) => ({ type: "steps", title, items });
const list = (title, items) => ({ type: "list", title, items });
const guide = (id, title, daTitle, text, daText, keywords = [], daKeywords = [], image) => ({
  id,
  title,
  summary: text,
  keywords,
  ...(image ? { image } : {}),
  blocks: [p(text)],
  i18n: { da: { title: daTitle, summary: daText, keywords: daKeywords, blocks: [p(daText)] } },
});

const ironBarRecipe = RESOURCE_MERGE_RECIPES.find((recipe) => recipe.output === "iron_bar") ?? { inputs: { iron_piece: 3 }, count: 1 };
const woodPlankRecipe = RESOURCE_MERGE_RECIPES.find((recipe) => recipe.output === "wood_plank") ?? { inputs: { wood_piece: 10 }, count: 1 };
const HELP_RESOURCE_NAMES = {
  iron_piece: { id: "iron_piece", name: RESOURCE_DEFS.iron_piece?.name ?? "Iron Piece", i18n: { da: { name: "jernstykke" } } },
  iron_bar: { id: "iron_bar", name: RESOURCE_DEFS.iron_bar?.name ?? "Iron Bar", i18n: { da: { name: "jernbar" } } },
  wood_piece: { id: "wood_piece", name: RESOURCE_DEFS.wood_piece?.name ?? "Wood Piece", i18n: { da: { name: "træstykke" } } },
  wood_plank: { id: "wood_plank", name: RESOURCE_DEFS.wood_plank?.name ?? "Wood Plank", i18n: { da: { name: "træplanke" } } },
};

function recipeMaterials(recipe, language, localize) {
  return Object.entries(recipe.inputs ?? {}).map(([id, count]) => `${count} ${localize(HELP_RESOURCE_NAMES[id] ?? RESOURCE_DEFS[id], "name", { language }) || id}`).join(", ");
}

export function helpTemplateParams(language = "en", localize = (entity, field) => entity?.[field] ?? "") {
  return {
    count: ironBarRecipe.count ?? 1,
    itemName: localize(HELP_RESOURCE_NAMES.iron_bar, "name", { language }),
    materialsInline: recipeMaterials(ironBarRecipe, language, localize),
    ironBarMaterials: recipeMaterials(ironBarRecipe, language, localize),
    woodPlankMaterials: recipeMaterials(woodPlankRecipe, language, localize),
    buildingName: "Blacksmith",
  };
}

